import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import type {KeyValue} from '@jetbrains/teamcity-ui/dist/utils'
import classnames from 'classnames'
import {memo} from 'react'

import styles from './FileTypeIcon.module.css'

export const Icons: KeyValue<string, string> = {
  file: 'file',
  zip: 'file-archive',
  rar: 'file-archive',
  as: 'file-as',
  aspectj: 'file-aspectj',
  config: 'file-config',
  css: 'file-css',
  diagram: 'file-diagram',
  dtd: 'file-dtd',
  go: 'file-go',
  graphql: 'file-gql',
  htaccess: 'file-htaccess',
  html: 'file-html',
  idl: 'file-idl',
  java: 'file-java',
  js: 'file-js',
  json: 'file-json',
  jsp: 'file-jsp',
  jspx: 'file-jspx',
  kt: 'file-kotlin',
  manifest: 'file-manifest',
  py: 'file-python',
  properties: 'file-properties',
  regexp: 'file-regexp',
  storyshot: 'file-text',
  tag: 'file-jsp',
  ts: 'file-ts',
  tsx: 'file-tsx',
  txt: 'file-text',
  unknown: 'file-unknown',
  wsdl: 'file-wsdl',
  xhtml: 'file-xhtml',
  xml: 'file-xml',
  xsd: 'file-xsd',
  yaml: 'file-yaml',
}
type Props = {
  type: string
  className?: string
}

function FileTypeIcon({type, className}: Props) {
  const icon = Icons[type] ?? 'file'
  const classes = classnames(styles.icon, className, icon === 'file' ? styles.file : undefined)
  return (
    <SvgIcon
      icon={icon}
      className={classes}
      title={Icons[type] != null ? `File type - ${type}` : ''}
    />
  )
}

export default memo(FileTypeIcon)
