import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import classNames from 'classnames'
import plur from 'plur'
import {useMemo, useCallback, Suspense} from 'react'
import {graphql, usePreloadedQuery, useQueryLoader} from 'react-relay'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import {useLazyLoading} from '../../../../../hocs/withLazyLoading'
import type {ChangeId} from '../../../../../types'
import {stringifyId} from '../../../../../types'
import {Namespace} from '../../../../../utils/namespace'
import BranchLabel from '../../../../common/BranchLabel/BranchLabel'
import Popup from '../../../../common/Popup/Popup.lazy'
import {getChange} from '../../Changes.selectors'

import type {ChangeBranchesQuery} from './__generated__/ChangeBranchesQuery.graphql'

import styles from './ChangeBranches.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

const query = graphql`
  query ChangeBranchesQuery($changeLocator: String!) {
    change(changeLocator: $changeLocator) {
      mergedInfo {
        branches {
          branch {
            name
            default
          }
        }
      }
    }
  }
`

type Props = {
  queryRef: PreloadedQuery<ChangeBranchesQuery>
}

function ChangeBranches({queryRef}: Props) {
  const {change} = usePreloadedQuery(query, queryRef)
  const {branches} = change?.mergedInfo ?? {}

  const filteredBranches = useMemo(
    () =>
      [
        ...new Map(
          branches?.branch
            ?.filter(branch => branch.name !== '<not_branched>')
            .map(item => [item.name, item]),
        ).values(),
      ].sort(a => (a.default ? -1 : 1)),
    [branches],
  )

  const firstBranch = filteredBranches[0]
  const otherBranchesCount = filteredBranches.length - 1

  const renderAnchor = useMemo(
    () => (
      <span className={styles.anchor}>{`+${otherBranchesCount} ${plur(
        'branch',
        'branches',
        otherBranchesCount,
      )}`}</span>
    ),
    [otherBranchesCount],
  )

  return (
    <>
      {firstBranch != null && (
        <BranchLabel
          className={styles.visibleBranchLabel}
          name={firstBranch.name}
          main={firstBranch.default}
          defaultTrim
          noLink
        />
      )}
      {filteredBranches.length > 1 && (
        <Dropdown anchor={renderAnchor} hoverMode>
          <Popup>
            <div className={styles.popup}>
              {filteredBranches.slice(1).map(branch => (
                <BranchLabel
                  key={branch.name}
                  className={styles.branchLabel}
                  name={branch.name}
                  main={branch.default}
                  noLink
                />
              ))}
            </div>
          </Popup>
        </Dropdown>
      )}
    </>
  )
}

type ContainerProps = {
  className?: string
  changeId: ChangeId
}

export default function ChangeBranchesContainer({className, changeId}: ContainerProps) {
  const [queryRef, loadQuery] = useQueryLoader<ChangeBranchesQuery>(query)
  const {personal} = useAppSelector(state => getChange(state, changeId)) ?? {}
  const changeLocator = `id:${stringifyId(changeId)},personal:${personal || false}`
  const fetchDetails = useCallback(() => loadQuery({changeLocator}), [changeLocator, loadQuery])

  const lazyLoadingProps = useLazyLoading<ChangeId, HTMLDivElement>({
    namespace: Namespace.CHANGE_BRANCHES,
    childUsesVisibility: false,
    ignoreFetcher: true,
    id: changeId,
    needsDetails: queryRef == null,
    fetchDetails,
    defaultVisible: false,
  })

  return (
    <div className={classNames(className, styles.wrapper)}>
      <div {...lazyLoadingProps.wrapperProps} />
      {queryRef != null && (
        <Suspense>
          <ChangeBranches queryRef={queryRef} />
        </Suspense>
      )}
    </div>
  )
}
