import type {ActionCreator, AppThunk} from '../../../actions/types'
import {noop} from '../../../utils/empty'

import buildPager from './BuildPager/BuildPager.slice'
import {getPager} from './Pager.selectors'
import type {PagerGroup} from './Pager.types'

export const lookDeeper =
  (update: () => unknown): (() => AppThunk<void>) =>
  () =>
  dispatch => {
    dispatch(buildPager.actions.incrementLookupLimit())
    update()
  }
export const changeCurrentBuildPage =
  (update: () => unknown = noop, group?: PagerGroup): ActionCreator<number> =>
  currentPage =>
  (dispatch, getState) => {
    const state = getState()
    const pager = group ? getPager(state, group) : null

    dispatch(buildPager.actions.changeCurrentPage(currentPage))

    if (!pager?.isClientFilter) {
      update()
    }
  }
export const gotoLastPage =
  (update: () => unknown, group: PagerGroup): (() => AppThunk<void>) =>
  () =>
  (dispatch, getState) => {
    const state = getState()
    const pager = getPager(state, group)
    const lastPage = Math.ceil(pager.total / pager.pageSize)
    dispatch(changeCurrentBuildPage(update)(lastPage))
  }
