import {objectToQuery} from '@jetbrains/teamcity-ui/dist/utils'

import {getOverviewHref} from '../../../../../routes'
import type {BuildId, BuildTypeId} from '../../../../../types'
import {BuildPageTabNamesEnum, BuildTypePageTabNamesEnum} from '../../../../../types'

export const getBuildChangesTabHref = (buildId: BuildId | undefined | null) =>
  `${getOverviewHref({buildId})}?${objectToQuery({buildTab: BuildPageTabNamesEnum.CHANGES})}`

export const getBuildTypePendingChangesTabHref = (
  buildTypeId: BuildTypeId | undefined | null,
  branch: string | undefined | null,
) =>
  `${getOverviewHref({buildTypeId})}?${objectToQuery({
    branch,
    buildTypeTab: BuildTypePageTabNamesEnum.PENDING_CHANGES,
  })}`
