import {resolveRelative} from '@jetbrains/teamcity-ui/dist/utils'

import type {BuildTypeId, ChangeId} from '../../../types'
import {stringifyId} from '../../../types'

export const getChangeExtensionsPath = ({
  changeId,
  buildTypeId,
  snippetId = 'ALL_SNIPPETS',
  personal,
}: {
  changeId: ChangeId
  buildTypeId?: BuildTypeId | undefined | null
  snippetId?: string
  personal?: boolean
}): string =>
  resolveRelative(`/app/placeId/changes`, {
    modId: stringifyId(changeId),
    buildTypeId: buildTypeId != null ? stringifyId(buildTypeId) : null,
    personal: personal != null ? personal.toString() : 'false',
    snippetId,
  })

export const getFileExtensionsPath = ({
  changeId,
  snippetId = 'ALL_SNIPPETS',
  personal,
  file,
}: {
  changeId: ChangeId
  snippetId?: string
  personal?: boolean
  file: string
}): string =>
  resolveRelative(`/app/placeId/changesFile`, {
    modId: stringifyId(changeId),
    personal: personal != null ? personal.toString() : 'false',
    file,
    snippetId,
  })
