import {createContext} from 'react'

export enum ChangeView {
  PREVIEW = 'preview',
  ADVANCED = 'advanced',
  OVERALL = 'overall',
}

type ChangesListContextType = {
  changeView?: ChangeView
  showFiles?: boolean
  withGraph?: boolean
  withExpandableLines?: boolean
  withChangesActions?: boolean
  withRevision?: boolean
}

export const DEFAULT_CHANGES_LIST_CONTEXT = {
  changeView: ChangeView.ADVANCED,
  showFiles: false,
  withGraph: true,
  withExpandableLines: true,
  withChangesActions: true,
  withRevision: true,
}

export const ChangeContext = createContext<ChangesListContextType>(DEFAULT_CHANGES_LIST_CONTEXT)
export const ChangesGraphIndentContext = createContext<number>(0)
