import type {AnchorProps} from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import {ControlsHeightContext} from '@jetbrains/ring-ui-built/components/global/controls-height'
import Message from '@jetbrains/ring-ui-built/components/message/message'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {memo, useCallback, useContext, useEffect, useId, useLayoutEffect, useMemo} from 'react'

import {useAppDispatch, useAppSelector} from '../../../hooks/react-redux'
import {useSetUserProperty} from '../../../hooks/useSetUserProperty'
import {useBooleanUserProperty} from '../../../hooks/useUserProperty'
import {emptyArray} from '../../../utils/empty'
import {UserProperties} from '../../../utils/userProperties'
import Tooltip from '../Tooltip/Tooltip'
import {useVisibilityRef} from '../Visible/Visible.hooks'

import {actionsHint} from './ActionsDropdown.slices'
import type {Props} from './ActionsDropdown.types'
import ActionsDropdownContent from './ActionsDropdownContent/ActionsDropdownContent'

import styles from './ActionsDropdown.module.css'

function ActionsDropdown(props: Props) {
  const {
    inline,
    showAlways,
    htmlAvailable,
    className,
    anchorClassName,
    data = emptyArray,
    icon = 'more-options',
    withHint,
    hintEntityName,
  } = props

  const hintDismissedProperty = useBooleanUserProperty(UserProperties.ACTIONS_HINT_DISMISSED)
  const setUserProperty = useSetUserProperty()
  const hintDismissedStore = useAppSelector(state => state.actionsHint.dismissed)
  const dispatch = useAppDispatch()
  const [ref, isVisible] = useVisibilityRef()
  const showHint = withHint && !hintDismissedProperty && !hintDismissedStore && isVisible
  useLayoutEffect(() => {
    if (showHint) {
      dispatch(actionsHint.actions.recordShowed())
    }
  }, [dispatch, showHint])
  useEffect(() => {
    if (hintDismissedStore && !hintDismissedProperty) {
      setUserProperty(UserProperties.ACTIONS_HINT_DISMISSED, 'true')
    }
  }, [hintDismissedProperty, hintDismissedStore, setUserProperty])
  const dismissHint = useCallback(() => dispatch(actionsHint.actions.dismiss()), [dispatch])
  const id = useId()

  const classes = classNames(className, styles.dropdown)
  const anchorClasses = classNames(styles.anchorButton, anchorClassName)
  const controlsHeight = useContext(ControlsHeightContext)
  const anchor = useCallback(
    ({active}: AnchorProps) => (
      <Tooltip className={styles.tooltip} delay={100} title="Actions" id={id}>
        <IconButton
          height={controlsHeight}
          aria-labelledby={id}
          withBorder={!inline}
          className={anchorClasses}
          icon={icon}
          title=""
          active={active}
        />
      </Tooltip>
    ),
    [id, controlsHeight, inline, anchorClasses, icon],
  )
  return useMemo(
    () =>
      showAlways !== true && !htmlAvailable && data.length === 0 ? null : (
        <div ref={ref}>
          <Dropdown onShow={showHint ? dismissHint : undefined} className={classes} anchor={anchor}>
            <ActionsDropdownContent {...props} />
          </Dropdown>
          {showHint && (
            <Message
              className={styles.hint}
              icon={null}
              title={`The ${hintEntityName} "Actions" menu is now here.`}
              onClose={dismissHint}
              direction={Directions.BOTTOM_LEFT}
              tailOffset={13}
              buttonProps={{className: styles.gotIt}}
            />
          )}
        </div>
      ),
    [
      showAlways,
      htmlAvailable,
      data,
      classes,
      anchor,
      props,
      showHint,
      dismissHint,
      hintEntityName,
      ref,
    ],
  )
}

export default memo(ActionsDropdown)
