import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import {resolveRelative} from '@jetbrains/teamcity-ui/dist/utils'
import classNames from 'classnames'
import deepEqual from 'fast-deep-equal'
import {useCallback, useMemo} from 'react'

import {useIsHighlightMyChangesAndInvestigations} from '../../../../hooks/useIsHighlightMyChangesAndInvestigations'
import useMyId from '../../../../hooks/useMyId'
import {usePermission} from '../../../../hooks/usePermission'
import type {ChangeId} from '../../../../types'
import {Permission, ROOT_PROJECT_ID} from '../../../../types'
import {BS} from '../../../../types/BS_types'
import Avatar, {Size} from '../../../common/Avatar/Avatar.container'
import Popup from '../../../common/Popup/Popup.lazy'
import {getChange} from '../Changes.selectors'
import {getCommiterName, getUsers} from '../Changes.utils'

import styles from './ChangeAuthor.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = {
  className?: string
  changeId: ChangeId
  withAvatar?: boolean
  inline?: boolean
}

function ChangeAuthor({className, changeId, withAvatar, inline}: Props) {
  const users = useAppSelector(state => getUsers(getChange(state, changeId)), deepEqual)
  const user = users.length === 1 ? users[0] : undefined
  const userId = user?.id
  const commiterName = useAppSelector(state => getCommiterName(getChange(state, changeId)))
  const vcsUsername = useAppSelector(state => getChange(state, changeId)?.username)
  const myId = useMyId()

  const name = user?.name
  const username = user?.username

  const onClickItsMe = useCallback(
    () => BS?.VcsUsername?.addVcsNameFromModification(changeId),
    [changeId],
  )

  const renderUsername = name && username ? ` (${username})` : ''
  const renderVcsUsername = `VCS username: ${vcsUsername}`
  const isHighlightMyChanges = useIsHighlightMyChangesAndInvestigations()

  const renderAuthor = useMemo(
    () => (
      <div className={styles.author}>
        {withAvatar && (
          <Avatar
            user={user}
            vcsUserName={vcsUsername}
            avatarClassName={classNames(styles.avatar, {
              [styles.othersAvatar]: isHighlightMyChanges && (user?.id == null || user.id !== myId),
            })}
            size={Size.Size20}
          />
        )}
        <div className={styles.username}>{commiterName}</div>
      </div>
    ),
    [commiterName, isHighlightMyChanges, myId, user, vcsUsername, withAvatar],
  )

  const canEditOwnProfile = usePermission(Permission.CHANGE_OWN_PROFILE, ROOT_PROJECT_ID)
  const canEditOtherProfiles = usePermission(Permission.CHANGE_USER, ROOT_PROJECT_ID)
  const renderItsMeButton = useMemo(
    () =>
      canEditOwnProfile && (
        <Button className={styles.itsMe} onClick={onClickItsMe} inline>
          {"It's me"}
        </Button>
      ),
    [canEditOwnProfile, onClickItsMe],
  )

  return useMemo(() => {
    const usersElement =
      users.length > 1 ? (
        <>
          <div className={styles.usersNote}>{`There are ${users.length} users with ${
            inline ? vcsUsername : 'this'
          } username:`}</div>
          {users.map(item => (
            <div className={styles.teamCityUser} key={item.id}>
              <span>
                <Avatar
                  className={styles.usersAvatarWrapper}
                  avatarClassName={styles.usersAvatar}
                  user={item}
                  size={Size.Size20}
                />
                {item.name ?? item.username}
              </span>
              {((item.id === myId && canEditOwnProfile) || canEditOtherProfiles) && (
                <Link
                  className={styles.editLink}
                  href={resolveRelative(
                    item.id === myId
                      ? '/profile.html?item=vcsUsernames'
                      : `/admin/editUser.html?userId=${item.id}&item=vcsUsernames`,
                  )}
                >
                  {'Edit usernames'}
                </Link>
              )}
            </div>
          ))}
        </>
      ) : null

    if (inline === true) {
      return (
        <div className={classNames(className, styles.inline)}>
          {userId != null ? (
            <div className={styles.inlineAuthor}>
              {renderAuthor}
              {`${renderUsername}, ${renderVcsUsername}`}
            </div>
          ) : (
            usersElement || (
              <div className={styles.teamCityUser}>
                {`Unknown (none of TeamCity users defined ${vcsUsername} username in their VCS username settings)`}
                {renderItsMeButton}
              </div>
            )
          )}
        </div>
      )
    }

    return vcsUsername ? (
      <Dropdown
        className={classNames(className, styles.usernameWrapper)}
        anchor={renderAuthor}
        data-test-change-item={'author'}
        clickMode={false}
        hoverMode
      >
        <Popup
          directions={[Directions.BOTTOM_LEFT, Directions.TOP_LEFT]}
          left={16}
          className={styles.userPopup}
        >
          {renderVcsUsername}
          {userId != null ? (
            <div className={styles.teamCityUser}>{`TeamCity user: ${
              name ?? username
            }${renderUsername}`}</div>
          ) : (
            usersElement || (
              <div className={styles.teamCityUser}>
                <span className={styles.unknownUser}>{'Unknown TeamCity user'}</span>
                {renderItsMeButton}
              </div>
            )
          )}
        </Popup>
      </Dropdown>
    ) : (
      <span className={styles.username}>{commiterName}</span>
    )
  }, [
    className,
    commiterName,
    inline,
    name,
    renderAuthor,
    renderItsMeButton,
    renderUsername,
    renderVcsUsername,
    userId,
    users,
    vcsUsername,
    canEditOtherProfiles,
    canEditOwnProfile,
    myId,
    username,
  ])
}

export default ChangeAuthor
