import {getBranchLocator} from '../../../rest/locators'
import type {Branch} from '../../../services/rest'
import type {BaseChange, BuildTypeId, FilterOptions, NormalizedChange} from '../../../types'
import {ChangesType, stringifyId} from '../../../types'
import escapeLocatorDimension from '../../../utils/escapeLocatorDimension'

import {VISIBLE_COUNT} from './Changes.consts'

export const getUsers = (change: BaseChange<unknown, unknown> | null | undefined) =>
  change?.commiter?.users.user ?? []
export const getSingleUser = (change: BaseChange<unknown, unknown> | null | undefined) => {
  const users = getUsers(change)
  return users.length === 1 ? users[0] : undefined
}

export const getCommiterName = (change: NormalizedChange | null | undefined): string => {
  const user = getSingleUser(change)
  return (user?.name ?? user?.username ?? change?.username ?? '').trim() || '<anonymous>'
}

export const toChangesType = (changesType: string | null | undefined): ChangesType | null => {
  switch (changesType) {
    case ChangesType.CHANGES:
      return ChangesType.CHANGES
    case ChangesType.ARTIFACTS:
      return ChangesType.ARTIFACTS
    default:
      return null
  }
}

export const getChangesLocator = (
  params: FilterOptions & {
    baseLocator: string
    unique?: boolean
    currentPage?: number | null
    count?: number
    lookupLimit?: number
  },
): string => {
  const {
    versionedSettings = true,
    userId,
    username,
    comment = '',
    path = '',
    revision = '',
    projectId,
    unique,
    showDependenciesChanges,
    baseLocator,
    currentPage,
    count = VISIBLE_COUNT,
    lookupLimit,
  } = params ?? {}
  return [
    baseLocator,
    unique != null ? `unique:${unique}` : '',
    versionedSettings ? '' : 'versionedSettings:false',
    projectId != null ? `affectedProject:(id:${projectId})` : '',
    userId != null && userId !== '' ? `user:(id:${stringifyId(userId)})` : '',
    username != null && username !== '' ? `username:${username}` : '',
    showDependenciesChanges != null ? `changesFromDependencies:${showDependenciesChanges}` : '', // TODO fix this when the https://youtrack.jetbrains.com/issue/TW-73600/Make-it-possible-to-get-changes-from-dependencies-without-changes-in-current-build issue is fixed
    comment !== ''
      ? `comment:(value:${escapeLocatorDimension(comment)},matchType:contains,ignoreCase:true)`
      : '',
    path !== ''
      ? `file:path:(value:${escapeLocatorDimension(path)},matchType:contains,ignoreCase:true)`
      : '',
    revision !== ''
      ? `version:(value:${escapeLocatorDimension(revision)},matchType:contains,ignoreCase:true)`
      : '',
    count != null ? `count:${count}` : '',
    count != null && currentPage != null ? `start:${count * (currentPage - 1)}` : '',
    lookupLimit != null ? `lookupLimit:${lookupLimit}` : '',
  ]
    .filter(Boolean)
    .join(',')
}

export const getPendingChangesBaseLocator = (
  buildTypeId: BuildTypeId,
  branch: Branch | null | undefined,
): string => {
  const buildTypeLocator = `buildType:(id:${stringifyId(buildTypeId)})`
  const branchLocator = getBranchLocator(branch)
  const policyLocator = branch == null ? 'policy:SINCE_LAST_BUILD_IN_ANY_BRANCH' : ''
  return [buildTypeLocator, branchLocator, policyLocator, `pending:true`].filter(Boolean).join(',')
}
