import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {memo, Suspense, useCallback, useContext} from 'react'

import TransformText from '../../../../containers/TransformText'
import {useIsAutodetectTimeZone} from '../../../../hooks/useIsAutodetectTimeZone'
import useMyId from '../../../../hooks/useMyId'
import {useHeightResizeObserver} from '../../../../hooks/useResizeObserver'
import type {BuildTypeId, ChangeId} from '../../../../types'
import {displayDate} from '../../../../utils/dateTimeUtils'
import ActionsDropdown from '../../../common/ActionsDropdown/ActionsDropdown.container'
import Details from '../../../common/Details/Details'
import InjectExpansion from '../../../common/InjectExtensions/InjectExtensions'
import {getChangeExtensionsPath} from '../../../common/InjectExtensions/InjectExtensions.utils'
import UncommitedChangeLabel from '../../../common/UncommitedChangeLabel/UncommitedChangeLabel'
import {
  PipelinesTarget,
  PipelinesTargetContext,
} from '../../../pages/PipelinesPages/contexts/targetContext'
import ChangeAuthor from '../ChangeAuthor/ChangeAuthor'
import ChangeRevisionLink from '../ChangeRevision/ChangeRevision'
import {getChange} from '../Changes.selectors'
import {getSingleUser} from '../Changes.utils'

import {ChangeContext, ChangesGraphIndentContext, ChangeView} from './Change.context'
import ChangeBranches from './ChangeBranches/ChangeBranches'
import ChangeDetails from './ChangeDetails/ChangeDetails'
import ChangeFilesLink from './ChangeFilesLink/ChangeFilesLink'
import ChangeFromSnapshotDependencyIcon from './ChangeFromSnapshotDependencyIcon/ChangeFromSnapshotDependencyIcon'
import ChangeStatus from './ChangeStatus/ChangeStatus'
import ChangeStatusCounters from './ChangeStatusCounters/ChangeStatusCounters'

import styles from './Change.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

const LARGE_ROW_LINE_HEIGHT = 20
const SMALL_ROW_LINE_HEIGHT = 24

type Props = {
  className?: string
  buildTypeId: BuildTypeId | null | undefined
  changeId: ChangeId
  toggleExpandedChange: (changeId: ChangeId) => unknown
  expanded?: boolean
  withAuthor?: boolean
}

function Change({
  changeId,
  buildTypeId,
  toggleExpandedChange,
  expanded = false,
  withAuthor = false,
}: Props) {
  const pipelineTarget = useContext(PipelinesTargetContext)
  const {changeView, showFiles, withExpandableLines, withChangesActions, withRevision} =
    useContext(ChangeContext)
  const changesGraphIndent = useContext(ChangesGraphIndentContext)
  const currentUserId = useMyId()
  const isAutodetectTimeZone = useIsAutodetectTimeZone()
  const date = useAppSelector(state => getChange(state, changeId)?.date)
  const comment = useAppSelector(state => getChange(state, changeId)?.comment)
  const version = useAppSelector(state => getChange(state, changeId)?.version)
  const personal = useAppSelector(state => getChange(state, changeId)?.personal)
  const storesProjectSettings = useAppSelector(
    state => getChange(state, changeId)?.storesProjectSettings,
  )
  const userId = useAppSelector(state => getSingleUser(getChange(state, changeId))?.id)

  const commentText = comment != null && comment !== '' ? comment : 'No comment'
  const expandCollapseRow = useCallback(
    () => toggleExpandedChange(changeId),
    [toggleExpandedChange, changeId],
  )

  const [innerHeight, measureRef] = useHeightResizeObserver()

  const lineBreakPosition = commentText.indexOf('\n')
  const isMultiline = lineBreakPosition !== -1 && lineBreakPosition !== commentText.length - 1

  const renderRow = () =>
    changeId != null && (
      <>
        <div className={styles.row}>
          {changeView === ChangeView.OVERALL ? (
            <div className={styles.chartCol}>
              <Suspense>
                <ChangeStatus changeId={changeId} />
              </Suspense>
            </div>
          ) : null}
          <div
            className={styles.commentCol}
            style={changesGraphIndent !== 0 ? {paddingLeft: `${changesGraphIndent}px`} : {}}
            data-test-change-item
          >
            <div className={styles.commentWrapper} data-test-change-item={'comment'}>
              <ChangeFromSnapshotDependencyIcon
                className={styles.changeFromSnapshotDependencyIcon}
                changeId={changeId}
              />
              {storesProjectSettings && (
                <SvgIcon
                  className={styles.settingsIcon}
                  title="Change in settings"
                  icon="filters"
                />
              )}
              {personal === true && (
                <UncommitedChangeLabel
                  iconClassName={classNames(styles.personalIcon, {
                    [styles.myPersonalIcon]: currentUserId === userId,
                  })}
                  onlyIcon
                />
              )}
              <TransformText
                className={classNames(styles.comment, {[styles.singleline]: expanded !== true})}
                buildTypeId={buildTypeId}
                changeId={changeId}
                personal={personal}
                text={
                  !expanded && isMultiline ? commentText.slice(0, lineBreakPosition) : commentText
                }
                lineHeight={
                  changeView === ChangeView.PREVIEW ? SMALL_ROW_LINE_HEIGHT : LARGE_ROW_LINE_HEIGHT
                }
                withLazyLoading
              />
              {isMultiline && expanded === false && (
                <div className={styles.multylineIcon}>{'[...]'}</div>
              )}
              {changeView === ChangeView.OVERALL ? (
                <ChangeBranches className={styles.branches} changeId={changeId} />
              ) : null}
            </div>
            {changeView === ChangeView.OVERALL ? (
              <ChangeStatusCounters changeId={changeId} />
            ) : null}
          </div>
          <div className={styles.authorAndDateCol}>
            {withAuthor ? (
              <Suspense fallback={<div className={styles.author} />}>
                <ChangeAuthor className={styles.author} changeId={changeId} withAvatar />
              </Suspense>
            ) : (
              <div className={styles.author} />
            )}
            {date != null && (
              <span className={styles.datetime} data-test-change-item="datetime">
                {` ${displayDate(date, isAutodetectTimeZone, true)}`}
              </span>
            )}
          </div>
          {withRevision && changeView !== ChangeView.PREVIEW && (
            <div className={styles.revisionCol}>
              {version != null ? (
                <ChangeRevisionLink
                  changeId={changeId}
                  date={date}
                  version={version}
                  personal={personal}
                  withDetailsPopup={changeView === ChangeView.OVERALL}
                  withShortView
                />
              ) : (
                'No revision'
              )}
            </div>
          )}
          <div className={styles.filesCol}>
            <ChangeFilesLink changeId={changeId} buildTypeId={buildTypeId} />
          </div>
          {withChangesActions === true && (
            <div className={styles.actionsCol} data-test-change-item={'actions'}>
              <InjectExpansion
                className={styles.externalViewer}
                path={getChangeExtensionsPath({changeId, personal, snippetId: 'changeViewers'})}
              />
              <ActionsDropdown
                entityHref={getChangeExtensionsPath({buildTypeId, changeId, personal})}
                anchorClassName={styles.actionsAnchor}
                showAlways
                inline
              />
            </div>
          )}
        </div>
        {showFiles !== true && withExpandableLines === true && (
          <SvgIcon
            className={styles.arrow}
            icon={expanded === true ? 'chevron-up' : 'chevron-down'}
          />
        )}
      </>
    )

  return (
    <div
      className={classNames(styles.item, {
        [styles.open]: expanded,
        [styles.closed]: !expanded,
        [styles.showFiles]: showFiles,
        [styles.smallPadding]: changeView === ChangeView.PREVIEW,
        [styles.jobDetailsSidebarTarget]: pipelineTarget === PipelinesTarget.JOB_DETAILS_SIDEBAR,
      })}
    >
      <div
        className={styles.psevdoItem}
        data-graph-id={`tr-mod-${changeId}`}
        data-expanded={expanded}
      />
      <Details
        headingClassName={styles.detailsHeading}
        level={2}
        label={commentText}
        open={expanded}
        summary={renderRow()}
        summaryClassName={styles.button}
        detailsWrapperClassName={styles.detailsWrapper}
        onToggle={expandCollapseRow}
        imitateHeading
        renderButtonAside
      >
        {expanded && (
          <div style={{height: innerHeight}} className={styles.outerContainer}>
            <div ref={measureRef} className={styles.innerContainer}>
              <ChangeDetails changeId={changeId} />
            </div>
          </div>
        )}
      </Details>
    </div>
  )
}

export default memo(Change)
