import type {State} from '../../../../reducers/types'
import type {FileChange} from '../../../../services/rest'
import type {ChangeId} from '../../../../types'
import {emptyArray} from '../../../../utils/empty'

export const getChangeFiles: (
  state: State,
  changeId: ChangeId | null | undefined,
) => ReadonlyArray<FileChange> = (state, changeId) =>
  changeId != null ? (state.changeFiles.changesFiles[changeId] ?? emptyArray) : emptyArray

export const hasChangeFiles: (arg0: State, arg1: ChangeId | null | undefined) => boolean = (
  state,
  changeId,
) => (changeId != null ? state.changeFiles.changesFiles[changeId] != null : false)
