import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import classNames from 'classnames'
import {memo, useContext, useMemo, useState} from 'react'

import type {ChangeId} from '../../../../../types'
import SequenceLoader from '../../../../common/SequenceLoader/SequenceLoader'
import ChangeDetailsInfo from '../../ChangeDetailsInfo/ChangeDetailsInfo'
import {ChangePageTabName} from '../../ChangeDetailsTabs/ChangeDetailsTabs.types'
import ChangeFiles from '../../ChangeFiles/ChangeFiles'
import {getChange} from '../../Changes.selectors'
import {ChangeContext, ChangesGraphIndentContext, ChangeView} from '../Change.context'

import {ChangeDetailsContext} from './ChangeDetails.context'

import styles from './ChangeDetails.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = {
  changeId: ChangeId | null | undefined
}

function ChangeDetails({changeId}: Props) {
  const changesGraphIndent = useContext(ChangesGraphIndentContext)
  const {changeView, showFiles} = useContext(ChangeContext)
  const {renderDetailsContent} = useContext(ChangeDetailsContext)

  const [currentTab, setCurrentTab] = useState(ChangePageTabName.PROBLEMS_TESTS)
  const change = useAppSelector(state => getChange(state, changeId))
  const filesCount = change?.files?.count ?? 0

  const renderLoader = useMemo(
    () => (
      <div style={changesGraphIndent !== 0 ? {paddingLeft: changesGraphIndent} : {}}>
        <LoaderInline>{'Loading...'}</LoaderInline>
      </div>
    ),
    [changesGraphIndent],
  )

  return changeId != null ? (
    <div
      className={classNames(styles.wrapper, {
        [styles.showFiles]: showFiles,
        [styles.smallPadding]: changeView === ChangeView.PREVIEW,
      })}
    >
      {renderDetailsContent != null ? (
        renderDetailsContent({changeId, currentTab, onSelectTab: setCurrentTab})
      ) : (
        <>
          {filesCount > 0 && (
            <SequenceLoader loader={renderLoader}>
              <ChangeFiles seqKey="ChangeFiles" changeId={changeId} />
            </SequenceLoader>
          )}
          {showFiles !== true && (
            <ChangeDetailsInfo className={styles.changeInfo} changeId={changeId} />
          )}
        </>
      )}
    </div>
  ) : null
}

export default memo(ChangeDetails)
