import plur from 'plur'
import {Suspense, useCallback} from 'react'
import {graphql, usePreloadedQuery, useQueryLoader} from 'react-relay'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import {useLazyLoading} from '../../../../../hocs/withLazyLoading'
import {getChangeHref} from '../../../../../routes'
import type {ChangeId} from '../../../../../types'
import {stringifyId} from '../../../../../types'
import {Namespace} from '../../../../../utils/namespace'
import RouterLink from '../../../../common/RouterLink/RouterLink'
import {ChangePageTabName} from '../../ChangeDetailsTabs/ChangeDetailsTabs.types'
import {getChange} from '../../Changes.selectors'

import type {ChangeStatusCountersQuery} from './__generated__/ChangeStatusCountersQuery.graphql'

import styles from './ChangeStatusCounters.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

export const changeStatusCountersQuery = graphql`
  query ChangeStatusCountersQuery($changeLocator: String!) {
    change(changeLocator: $changeLocator) {
      status {
        totalProblems
        newFailedTests
        otherFailedTests
        pendingBuildTypes
        successfulBuilds
        runningSuccessfullyBuilds
        compilationErrorBuilds {
          count
        }
        ...ChangeStatus
      }
    }
  }
`

type Props = {
  changeId: ChangeId
}

type InnerProps = Props & {
  queryRef: PreloadedQuery<ChangeStatusCountersQuery>
}

function ChangeStatusCounters({changeId, queryRef}: InnerProps) {
  const {personal} = useAppSelector(state => getChange(state, changeId)) ?? {}

  const {change} = usePreloadedQuery(changeStatusCountersQuery, queryRef)
  const {status} = change ?? {}

  const totalProblems = status?.totalProblems ?? 0
  const newFailedTests = status?.newFailedTests ?? 0
  const otherFailedTests = status?.otherFailedTests ?? 0
  const pending = status?.pendingBuildTypes ?? 0
  const successfulBuilds = status?.successfulBuilds ?? 0
  const runningSuccessfullyBuilds = status?.runningSuccessfullyBuilds ?? 0
  const compilationErrorBuilds = status?.compilationErrorBuilds?.count ?? 0
  const hasProblems = newFailedTests > 0 || otherFailedTests > 0 || totalProblems > 0

  let label = 'Success'
  let href = null

  if (hasProblems) {
    const allTests = otherFailedTests + newFailedTests
    href = getChangeHref({changeId, personal, tab: ChangePageTabName.PROBLEMS_TESTS})
    label = [
      compilationErrorBuilds
        ? `${compilationErrorBuilds} compilation ${plur('error', compilationErrorBuilds)}`
        : null,
      allTests
        ? `${allTests} ${plur('test', allTests)} failed${
            newFailedTests ? ` (${newFailedTests} new)` : ''
          }`
        : null,
      totalProblems ? `${totalProblems} build ${plur('problem', totalProblems)}` : null,
    ]
      .filter(Boolean)
      .join(', ')
  } else if (pending > 0 && successfulBuilds === 0 && runningSuccessfullyBuilds === 0) {
    href = getChangeHref({changeId, personal, tab: ChangePageTabName.BUILDS})
    label = `${pending} pending build ${plur('configuration', pending)}`
  }

  return href != null ? (
    <RouterLink className={styles.counters} to={href}>
      {label}
    </RouterLink>
  ) : (
    <span className={styles.counters}>{label}</span>
  )
}

export default function ChangeStatusCountersContainer({changeId}: Props) {
  const [queryRef, loadQuery] = useQueryLoader<ChangeStatusCountersQuery>(changeStatusCountersQuery)
  const {personal} = useAppSelector(state => getChange(state, changeId)) ?? {}
  const changeLocator = `id:${stringifyId(changeId)},personal:${personal || false}`
  const fetchDetails = useCallback(() => loadQuery({changeLocator}), [changeLocator, loadQuery])
  const lazyLoadingProps = useLazyLoading<ChangeId, HTMLDivElement>({
    namespace: Namespace.CHANGE_STATUS,
    childUsesVisibility: false,
    ignoreFetcher: true,
    id: changeId,
    needsDetails: queryRef == null,
    fetchDetails,
    defaultVisible: false,
  })

  const fallback = <span className={styles.counters}>{'Loading...'}</span>
  return (
    <>
      <div {...lazyLoadingProps.wrapperProps} />
      {queryRef != null ? (
        <Suspense fallback={fallback}>
          <ChangeStatusCounters changeId={changeId} queryRef={queryRef} />
        </Suspense>
      ) : (
        fallback
      )}
    </>
  )
}
