import List from '@jetbrains/ring-ui-built/components/list/list'
import Loader from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import type {PopupAttrs} from '@jetbrains/ring-ui-built/components/popup/popup'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import classNames from 'classnames'
import * as React from 'react'
import {useNavigate} from 'react-router'

import {useUpdateResults} from '../../../../contexts/update'
import {noop} from '../../../../utils/empty'
import InjectHtml from '../../InjectHtml/InjectHtml'
import Popup from '../../Popup/Popup.lazy'
import Styles from '../../Styles/Styles'
import styles from '../ActionsDropdown.module.css'
import type {Props as ActionsDropdownProps} from '../ActionsDropdown.types'
import {htmlToListItems} from '../ActionsDropdown.utils'

const DEFAULT_POPUP_DIRECTIONS = [
  Directions.BOTTOM_LEFT,
  Directions.BOTTOM_RIGHT,
  Directions.TOP_LEFT,
  Directions.TOP_RIGHT,
]

type Props = ActionsDropdownProps & Partial<PopupAttrs>

function ActionsDropdownContent({
  html,
  htmlAvailable,
  path,
  skipAssignInvestigation,
  data = [],
  onCloseAttempt,
  className,
  anchor,
  anchorClassName,
  showAlways,
  inline,
  entityHref,
  preload,
  update,
  reload = noop,
  beforeList,
  ...restProps
}: Props) {
  const updateFromContext = useUpdateResults()
  const navigate = useNavigate()
  const htmlItems = React.useMemo(() => {
    if (path == null || (html != null && !htmlAvailable)) {
      return []
    }

    function handleUpdate() {
      const updateFn = update ?? updateFromContext
      updateFn()
      reload()
    }

    return [
      ...(data.length > 0
        ? [
            {
              key: 'htmlSeparator',
              rgItemType: List.ListProps.Type.SEPARATOR,
            },
          ]
        : []),
      ...(html != null
        ? htmlToListItems(html, skipAssignInvestigation, navigate, handleUpdate)
        : [
            {
              disabled: true,
              key: 'htmlLoader',
              label: <Loader>{'Loading...'}</Loader>,
            },
          ]),
    ]
  }, [
    data.length,
    html,
    htmlAvailable,
    navigate,
    path,
    reload,
    skipAssignInvestigation,
    update,
    updateFromContext,
  ])

  const items = React.useMemo(
    () => [
      ...data.map(item => ({
        ...item,
        className: classNames(item.className, styles.item),
        hoverClassName: classNames(item.hoverClassName, styles.hoverItem),
      })),
      ...htmlItems,
    ],
    [data, htmlItems],
  )
  return (
    <>
      {html != null && htmlAvailable && <Styles html={html} />}
      <Popup
        directions={DEFAULT_POPUP_DIRECTIONS}
        offset={4}
        onCloseAttempt={onCloseAttempt}
        {...restProps}
      >
        {beforeList}
        {items.length > 0 && (
          <List
            shortcuts
            data={items}
            renderOptimization={false}
            onSelect={() => onCloseAttempt?.()}
          />
        )}
        {path != null && (
          <div hidden>
            <InjectHtml
              reloadOnPermissionsChange={preload !== true && inline === true}
              path={path}
              TagName="ul"
              loaderClassName={styles.loader}
            />
          </div>
        )}
      </Popup>
    </>
  )
}
export default ActionsDropdownContent
