import type {WritableKeyValue} from '@jetbrains/teamcity-ui/dist/utils'

export const keysToHashMap = (
  array: Array<string | undefined>,
): WritableKeyValue<string, boolean> =>
  array.reduce((acc: WritableKeyValue<string, boolean>, curr) => {
    if (!curr) {
      return acc
    }

    acc[curr] = true
    return acc
  }, {})
