import Link from '@jetbrains/ring-ui-built/components/link/link'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import {skipToken} from '@reduxjs/toolkit/query'
import classNames from 'classnames'
import plur from 'plur'
import {memo, useCallback, useContext} from 'react'

import {getClassicUIDiffBetweenTwoFiles} from '../../../../selectors'
import type {FileChange} from '../../../../services/rest'
import {restApi} from '../../../../services/rest'
import type {BuildTypeId, ChangeId} from '../../../../types'
import ActionsDropdown from '../../../common/ActionsDropdown/ActionsDropdown.container'
import InjectExpansion from '../../../common/InjectExtensions/InjectExtensions'
import {getFileExtensionsPath} from '../../../common/InjectExtensions/InjectExtensions.utils'
import MiddleEllipsis from '../../../common/MiddleEllipsis/MiddleEllipsis'
import {useSequenceLoaderReadyHandler} from '../../../common/SequenceLoader/SequenceLoader.hooks'
import type {SeqProps} from '../../../common/SequenceLoader/SequenceLoader.types'
import {ChangeContext, ChangesGraphIndentContext, ChangeView} from '../Change/Change.context'
import {getChange} from '../Changes.selectors'

import {getChangeFilesArg} from './ChangeFiles.rest'
import {getChangeFiles, hasChangeFiles} from './ChangeFiles.selectors'
import FileTypeIcon from './FileTypeIcon/FileTypeIcon'

import styles from './ChangeFiles.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = SeqProps & {
  className?: string
  changeId: ChangeId
  buildTypeId?: BuildTypeId | null | undefined
  withHeading?: boolean
}

const MAX_FILE_NAME_LENGTH = 75

function ChangeFiles({className, changeId, buildTypeId, withHeading}: Props) {
  const changesGraphIndent = useContext(ChangesGraphIndentContext)
  const {changeView, showFiles} = useContext(ChangeContext)
  const personal = useAppSelector(state => getChange(state, changeId)?.personal)
  const files = useAppSelector(state => getChangeFiles(state, changeId))
  const isReady = useAppSelector(state => hasChangeFiles(state, changeId))

  useSequenceLoaderReadyHandler(isReady)
  restApi.endpoints.getChangeFiles.useQuerySubscription(
    showFiles ? skipToken : getChangeFilesArg(changeId, buildTypeId, personal),
  )

  const renderFile = useCallback(
    ({file: originalFile, changeType, directory}: FileChange) => {
      if (originalFile == null || changeType == null) {
        return null
      }

      // TODO ivanov.vladimir remove when https://youtrack.jetbrains.com/issue/TW-65542 is fixed
      const revisionParts = originalFile.split(/\|\|/g)
      const file = revisionParts[revisionParts.length - 1]
      const fileParts = file.split('.')
      const pathParts = file.split(/\//g)
      const fileType = fileParts[fileParts.length - 1]

      const renderName = (
        <MiddleEllipsis
          title={originalFile}
          tailLength={
            file.length > MAX_FILE_NAME_LENGTH && pathParts.length > 1
              ? pathParts[pathParts.length - 1].length + 1
              : 0
          }
        >
          {file}
        </MiddleEllipsis>
      )

      return (
        <div key={originalFile} className={styles.outerItemContainer}>
          <div
            className={styles.innerItemContainer}
            style={changesGraphIndent !== 0 ? {paddingLeft: changesGraphIndent} : {}}
          >
            <div
              className={classNames(
                styles.changeTypeCol,
                styles[changeType as keyof typeof styles],
              )}
            >
              {changeType}
            </div>
            <div className={styles.nameCol}>
              <div className={styles.icon}>
                {directory ? (
                  <SvgIcon icon="folder" title="Directory" />
                ) : (
                  <FileTypeIcon type={fileType} />
                )}
              </div>
              {directory ? (
                <span className={styles.name}>{renderName}</span>
              ) : (
                <Link
                  className={styles.name}
                  href={getClassicUIDiffBetweenTwoFiles({changeId, personal, file: originalFile})}
                  title={originalFile}
                  target="_blank"
                  rel="noreferrer"
                >
                  {renderName}
                </Link>
              )}
            </div>
            {!directory && (
              <div className={styles.actionsCol}>
                <InjectExpansion
                  className={styles.externalViewer}
                  path={getFileExtensionsPath({
                    changeId,
                    personal,
                    file: originalFile,
                    snippetId: 'changeViewers',
                  })}
                />
                <ActionsDropdown
                  entityHref={getFileExtensionsPath({changeId, file: originalFile, personal})}
                  anchorClassName={styles.actionsAnchor}
                  showAlways
                  inline
                />
              </div>
            )}
          </div>
        </div>
      )
    },
    [changeId, changesGraphIndent, personal],
  )
  return changeId != null ? (
    <div
      className={classNames(className, {[styles.smallPadding]: changeView === ChangeView.PREVIEW})}
    >
      {showFiles !== true && withHeading !== false && (
        <div
          className={styles.heading}
          style={changesGraphIndent !== 0 ? {paddingLeft: changesGraphIndent} : {}}
        >{`${files.length} ${plur('File', files.length)}`}</div>
      )}
      <div>{files.map(renderFile)}</div>
    </div>
  ) : null
}

export default memo(ChangeFiles)
