import {withProps, withHandlers} from 'recompose'

import compose from 'lodash/flowRight'
import * as React from 'react'
import {connect} from 'react-redux'

import type {State} from '../../../reducers/types'
import {getHrefWithQueryParams, withLocation} from '../../../routes'
import {queryToObject} from '../../../utils/queryParams'

import Pager from './Pager'
import {changeCurrentBuildPage} from './Pager.actions'
import {getPager} from './Pager.selectors'
import {PagerGroup} from './Pager.types'
import type {Props, ReduxOwnProps, StateProps, PagerHelperProps} from './Pager.types'
import {hasItemsOnPage} from './Pager.utils'

const mapStateToProps = (state: State, props: ReduxOwnProps): StateProps => {
  const {group} = props
  const pager = getPager(state, group)
  const {pageSize, total, openTotal, loadedLessThanRequested, hasMore} = pager
  const currentPage = Number(props.page) || 1
  let show: boolean | undefined =
    hasItemsOnPage(currentPage, pager) ||
    loadedLessThanRequested === false ||
    currentPage !== 1 ||
    hasMore === false

  if (group === PagerGroup.TEST || group === PagerGroup.CHANGE_LOG) {
    show = !(loadedLessThanRequested === true && currentPage === 1)
  }

  return {
    currentPage,
    pageSize,
    total,
    openTotal,
    show,
  }
}

class PagerContainer extends React.Component<Props> {
  render() {
    const {
      warningClassName,
      warningComponent: WarningComponent,
      group,
      show,
      isLoading,
      hasError,
      ...restProps
    } = this.props
    return (
      <React.Fragment>
        {WarningComponent != null && (
          <WarningComponent
            className={warningClassName}
            group={group}
            isShow={show}
            isLoading={isLoading}
            hasError={hasError}
          />
        )}
        <Pager show={show} {...restProps} />
      </React.Fragment>
    )
  }
}

export const withPagerHelper = compose(
  withLocation,
  connect(),
  withProps(({location}: PagerHelperProps) => ({
    page: queryToObject(location?.search).page,
  })),
  withHandlers({
    changeCurrentPage:
      ({location, navigate, group, updateResults, dispatch}) =>
      (page: number) => {
        navigate(
          getHrefWithQueryParams(location, null, params => ({
            ...params,
            page: String(page),
          })),
        )
        if (group === PagerGroup.BUILD) {
          dispatch(changeCurrentBuildPage(updateResults, group)(page))
        }
      },
  }),
)
export default compose(
  React.memo,
  withPagerHelper,
  connect(mapStateToProps, null),
  React.memo,
)(PagerContainer)
