import 'core-js/modules/es.array.to-reversed' // https://github.com/Fyrd/caniuse/issues/6670
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import type {KeyValue} from '@jetbrains/teamcity-ui/dist/utils'
import * as React from 'react'
import {Suspense, useMemo, useRef} from 'react'

import isVisualTest from '../../../utils/isVisualTest'
import {useIncremental} from '../Incremental/Incremental'

import {
  SequenceLoaderContext,
  useOnResetLoadingState,
  useSequenceLoaderReadyHandler,
} from './SequenceLoader.hooks'
import type {Child, Props, SequenceLoaderChildProps} from './SequenceLoader.types'
import {keysToHashMap} from './SequenceLoader.utils'

export function SequenceLoaderChild({children}: SequenceLoaderChildProps) {
  return <>{children}</>
}

type SequenceLoaderItemProps = {
  child: Child | null | undefined
  seqKey?: string
  onReady: (seqKey?: string) => unknown
  isLoading: boolean
}

function SequenceLoaderItem({child, seqKey, onReady, isLoading}: SequenceLoaderItemProps) {
  const handler = React.useCallback(() => onReady(seqKey), [onReady, seqKey])
  return (
    <SequenceLoaderContext.Provider
      value={useMemo(() => ({onReady: handler, isLoading}), [handler, isLoading])}
    >
      {child}
    </SequenceLoaderContext.Provider>
  )
}

const isTest = process.env.NODE_ENV === 'test' || isVisualTest()

function SequenceLoader({
  className,
  itemClassName,
  loader,
  showFirstLoadingItem = false,
  waitForAllLoaded,
  children,
  withIncrementalRendering,
  reverse,
}: Props) {
  const flatChildren = React.useMemo(() => React.Children.toArray(children) as Child[], [children])
  const validElements = React.useMemo(
    () => flatChildren.filter((child: Child) => child.props.seqKey != null),
    [flatChildren],
  )
  const sortedKeys = React.useMemo(() => {
    const keys = flatChildren.map((child: Child) => child.props.seqKey)
    return reverse ? keys.toReversed() : keys
  }, [flatChildren, reverse])
  const offKeys = React.useMemo<Array<string | undefined>>(
    () =>
      validElements
        .filter((child: Child) => child.props.seqOff)
        .map((child: Child) => child.props.seqKey),
    [validElements],
  )
  const [readyElements, setReadyElements] = React.useState<KeyValue<string, boolean>>(
    keysToHashMap(offKeys),
  )
  const setReadyElementsHandler = React.useCallback((elements: (string | undefined)[]) => {
    setReadyElements(state => {
      const newElements = elements.filter(element => element && !state[element])
      return newElements.length > 0
        ? {
            ...state,
            ...keysToHashMap(newElements),
          }
        : state
    })
  }, [])

  const onReady = React.useCallback(
    (seqKey?: string) => setReadyElementsHandler([seqKey]),
    [setReadyElementsHandler],
  )

  const isLoading = sortedKeys.length > Object.keys(readyElements).length
  const isReadyItemAndAllPreviousSet = useRef(new Set())
  const isReadyItemAndAllPrevious = (seqKey?: string): boolean => {
    if (waitForAllLoaded) {
      return !isLoading
    }
    if (isReadyItemAndAllPreviousSet.current.has(seqKey)) {
      return true
    }
    const result = !!seqKey && !!readyElements[seqKey] && isReadyAllPrevious(seqKey)
    if (result) {
      isReadyItemAndAllPreviousSet.current.add(seqKey)
    }
    return result
  }

  function isReadyAllPrevious(seqKey?: string) {
    const index = sortedKeys.indexOf(seqKey)
    return index === 0 || isReadyItemAndAllPrevious(sortedKeys[index - 1])
  }

  const renderLoader = React.useMemo(
    () =>
      loader ?? (
        <div>
          <LoaderInline>{'Loading...'}</LoaderInline>
        </div>
      ),
    [loader],
  )
  useOnResetLoadingState(() => {
    isReadyItemAndAllPreviousSet.current = new Set()
    setReadyElementsHandler(offKeys)
  })
  const renderCount = useIncremental(
    validElements.length,
    withIncrementalRendering && !isTest ? 1 : validElements.length,
  )
  useSequenceLoaderReadyHandler(!isLoading && renderCount >= validElements.length)

  return (
    <div className={className}>
      {validElements.slice(0, renderCount).map(child => {
        const {seqKey} = child.props
        return (
          <div
            key={seqKey}
            className={itemClassName}
            hidden={
              showFirstLoadingItem
                ? !isReadyAllPrevious(seqKey)
                : !isReadyItemAndAllPrevious(seqKey)
            }
          >
            <Suspense fallback={loader}>
              <SequenceLoaderItem
                isLoading={isLoading}
                seqKey={child.props.seqKey}
                child={child}
                onReady={onReady}
              />
            </Suspense>
          </div>
        )
      })}
      {(!showFirstLoadingItem && isLoading) || renderCount < validElements.length
        ? renderLoader
        : null}
    </div>
  )
}

export default SequenceLoader
