import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import {skipToken} from '@reduxjs/toolkit/query'
import classNames from 'classnames'
import plur from 'plur'
import type {ReactElement} from 'react'
import {memo, useMemo} from 'react'
import {shallowEqual} from 'react-redux'

import EntityPath from '../../../../../containers/EntityPath'
import {useSlice} from '../../../../../hooks/useSlice'
import {getProject} from '../../../../../selectors'
import {restApi} from '../../../../../services/rest'
import type {ChangeId, RevisionId, VcsRootId} from '../../../../../types'
import {getProjectFilter, ROOT_PROJECT_ID, stringifyId} from '../../../../../types'
import Popup from '../../../../common/Popup/Popup.lazy'
import {getModificationsOfChangeArg} from '../../Changes.rest'
import {
  getChange,
  getUniqueVcsRootIds,
  getVcsRoot,
  getVcsRootInstance,
} from '../../Changes.selectors'

import styles from './ChangeRevisionDropdown.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

const POPUP_DIRECTIONS = [
  Directions.BOTTOM_LEFT,
  Directions.TOP_LEFT,
  Directions.BOTTOM_RIGHT,
  Directions.TOP_RIGHT,
]

type Props = {
  changeId?: ChangeId | undefined | null
  version: RevisionId | undefined | null
  anchor: ReactElement
  initShown?: boolean
}

type TogglePayloads = {
  onShow: void
  onHide: void
}

type VcsRootProps = {
  vcsRootId: VcsRootId | null | undefined
  current?: boolean
}

function VcsRoot({vcsRootId, current}: VcsRootProps) {
  const vcsRoot = useAppSelector(state => getVcsRoot(state, vcsRootId))

  const {name, project} = vcsRoot ?? {}
  const {id: projectId} = project ?? {}

  const {parentProjectId} = useAppSelector(state => getProject(state, projectId)) ?? {}

  if (vcsRoot == null) {
    return null
  }

  return (
    <div className={classNames(styles.vcsRoot, {[styles.currentVcsRoot]: current})}>
      <div
        className={styles.vcsRootNameColumn}
        title={current ? `${name} (current vcs root)` : name}
      >
        {name}
      </div>

      <div className={styles.pathColumn}>
        {projectId === ROOT_PROJECT_ID ? (
          '<Root project>'
        ) : (
          <EntityPath
            projectId={projectId}
            projectOrBuildTypeNode={
              parentProjectId != null ? getProjectFilter(parentProjectId) : null
            }
            withLeafStatusIcon={false}
            withCollapsing
          />
        )}
      </div>
    </div>
  )
}

function ChangeRevisionDropdown({changeId, version, anchor, initShown}: Props) {
  const {vcsRootInstance} = useAppSelector(state => getChange(state, changeId)) ?? {}
  const {'vcs-root': currentVcsRootId} =
    useAppSelector(state => getVcsRootInstance(state, vcsRootInstance)) ?? {}

  const locator = `id:${stringifyId(changeId)},personal:false`
  const vcsRootIds = useAppSelector(state => getUniqueVcsRootIds(state, changeId), shallowEqual)

  const [dropdownOpen, {onShow, onHide}] = useSlice<boolean, TogglePayloads>(
    {
      onShow: () => true,
      onHide: () => false,
    },
    initShown ?? false,
  )
  const {isReady} = restApi.endpoints.getModificationsOfChange.useQuery(
    dropdownOpen ? getModificationsOfChangeArg(locator) : skipToken,
    {
      selectFromResult: ({data}) => ({isReady: data != null}),
    },
  )

  const renderContent = useMemo(
    () => (
      <div className={styles.popup}>
        <div className={styles.heading}>{'Revision'}</div>
        <div className={styles.revision}>{version}</div>
        <div className={styles.heading}>{`VCS ${plur('root', vcsRootIds.length)}`}</div>
        <div className={styles.vcsRoots}>
          {vcsRootIds.map(id => (
            <VcsRoot
              key={id}
              vcsRootId={id}
              current={currentVcsRootId === id && vcsRootIds.length > 1}
            />
          ))}
        </div>
      </div>
    ),
    [currentVcsRootId, vcsRootIds, version],
  )

  return (
    <Dropdown
      className={classNames({[styles.loading]: !isReady})}
      anchor={anchor}
      onShow={onShow}
      onHide={onHide}
      hoverMode
      initShown={initShown}
    >
      <Popup directions={POPUP_DIRECTIONS}>{isReady ? renderContent : ''}</Popup>
    </Dropdown>
  )
}

export default memo(ChangeRevisionDropdown)
