import alertService from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import type {ListDataItem} from '@jetbrains/ring-ui-built/components/list/consts'
import classNames from 'classnames'
import type * as React from 'react'
import type {NavigateFunction} from 'react-router'

import {getOverviewHref} from '../../../routes'
import type {ActiveEntityURLProps} from '../../../types'
import {BS} from '../../../types/BS_types'

import styles from './ActionsDropdown.module.css'

const ALERT_TIMEOUT = 5000
const parser = new DOMParser()

type ActionResult = {
  redirectTo?: ActiveEntityURLProps
  alert?: string
}

export function htmlToListItems(
  html: string,
  skipAssignInvestigation = false,
  navigate: NavigateFunction,
  update: () => unknown,
): ListDataItem[] {
  const root = parser.parseFromString(html, 'text/html')
  const links = [
    ...root.querySelectorAll<HTMLAnchorElement>(
      `a${skipAssignInvestigation ? ':not(.assignInvestigationAction)' : ''}`,
    ),
  ].filter(link => link.closest('.modalDialog') == null)
  return links.map((link): ListDataItem => {
    const text = link.textContent?.trim() || link.title
    const onclick = link.getAttribute('onclick')
    const href = link.getAttribute('href')
    const target = link.getAttribute('target') ?? undefined
    const prevSibling = link.previousElementSibling
    const getHandleClick = ():
      | ((
          event: Event | React.SyntheticEvent,
        ) => Promise<ActionResult | null | undefined> | null | undefined)
      | null
      | undefined => {
      try {
        return onclick != null ? (new Function('event', onclick) as any) : null // eslint-disable-line no-new-func
      } catch (e) {
        return null
      }
    }
    const handleClick = getHandleClick()
    return {
      key: text,
      className: styles.item,
      hoverClassName: styles.hoverItem,
      href: href != null && href !== '#' ? href : undefined,
      target,
      label: (
        <>
          {prevSibling?.classList.contains('icon16') ? (
            <span
              className={styles.icon}
              dangerouslySetInnerHTML={{
                __html: prevSibling.outerHTML,
              }}
            />
          ) : undefined}
          <span className={classNames(styles.itemText, link.className)}>{text}</span>
        </>
      ),
      onClick:
        handleClick != null
          ? async (_, e) => {
              const result: ActionResult | null | undefined = await handleClick(e)
              const {redirectTo, alert} = result ?? {}
              if (redirectTo != null) {
                navigate(getOverviewHref(redirectTo))
                return
              }
              if (alert != null) {
                alertService.message(alert, ALERT_TIMEOUT)
              }

              update()
            }
          : undefined,
    }
  })
}

export const getActionsPath = (entityHref: string | null | undefined) => {
  if (entityHref == null) {
    return null
  }

  try {
    const BUILD_TYPE_PARAM = 'buildTypeId'
    const url = new URL(entityHref)
    const buildTypeId = url.searchParams.get(BUILD_TYPE_PARAM) ?? ''

    /*
     * Fix: Setting the `buildTypeId` parameter to the end of the search params
     * to avoid the issue of the requested HTML due to uncorrect the `buildTypeId` value
     */
    url.searchParams.set('actionsOnly', 'true')
    url.searchParams.delete(BUILD_TYPE_PARAM)
    url.searchParams.append(BUILD_TYPE_PARAM, buildTypeId)

    return url.href
  } catch (e) {
    BS?.Log?.error(e, 'URL: ', entityHref)
    return null
  }
}
