import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {memo} from 'react'

import styles from './UncommitedChangeLabel.module.css'

type Props = {
  className?: string
  iconClassName?: string
  onlyIcon?: boolean
}

function UncommitedChangeLabel({className, iconClassName, onlyIcon}: Props) {
  return (
    <div
      className={classNames(className, styles.label)}
      title={'Uncommitted change from personal build'}
    >
      <SvgIcon className={classNames(iconClassName, styles.icon)} icon="user" />
      {!onlyIcon ? <span>{'Uncommitted change'}</span> : null}
    </div>
  )
}

export default memo(UncommitedChangeLabel)
