import {memo, useContext} from 'react'

import type {ChangeId} from '../../../../types'
import {ChangesGraphIndentContext} from '../Change/Change.context'
import ChangeRevisionLink from '../ChangeRevision/ChangeRevision'
import {getChange, getVcsRoot, getVcsRootInstance} from '../Changes.selectors'

import styles from './ChangeDetailsInfo.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = {
  className?: string
  changeId: ChangeId | null | undefined
}

function ChangeDetailsInfo({className, changeId}: Props) {
  const changesGraphIndent = useContext(ChangesGraphIndentContext)
  const change = useAppSelector(state => getChange(state, changeId))
  const vcsRootInstance = useAppSelector(state =>
    getVcsRootInstance(state, change?.vcsRootInstance),
  )
  const vcsRoot = useAppSelector(state => getVcsRoot(state, vcsRootInstance?.['vcs-root']))

  const {version, personal} = change ?? {}
  const {name: vcsRootName} = vcsRoot ?? {}

  return version != null && vcsRootName != null ? (
    <div className={className}>
      <div style={changesGraphIndent !== 0 ? {paddingLeft: changesGraphIndent} : {}}>
        <div className={styles.row}>
          <span className={styles.rowHeading}>{'Revision'}</span>
          {': '}
          <ChangeRevisionLink
            changeId={changeId}
            version={version}
            personal={personal ?? false}
            withCopyButton
          />
        </div>
        <div className={styles.row}>
          <span className={styles.rowHeading}>{'VCS root'}</span>
          {': '}
          {vcsRootName}
        </div>
      </div>
    </div>
  ) : null
}

export default memo(ChangeDetailsInfo)
