import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import {H3} from '@jetbrains/ring-ui-built/components/heading/heading'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import classNames from 'classnames'
import type {ReactNode, SyntheticEvent} from 'react'
import {Suspense, useCallback} from 'react'
import {graphql, useFragment, useLazyLoadQuery, useQueryLoader} from 'react-relay'

import {getChangeHref} from '../../../../../routes'
import type {ChangeId} from '../../../../../types'
import {stringifyId} from '../../../../../types'
import Icon from '../../../../common/Icon/Icon'
import Popup from '../../../../common/Popup/Popup.lazy'
import RouterLinkWrapper from '../../../../common/RouterLinkWrapper/RouterLinkWrapper'
import {ChangePageTabName} from '../../ChangeDetailsTabs/ChangeDetailsTabs.types'
import {getChange} from '../../Changes.selectors'
import type {ChangeStatusCountersQuery} from '../ChangeStatusCounters/__generated__/ChangeStatusCountersQuery.graphql'
import {changeStatusCountersQuery} from '../ChangeStatusCounters/ChangeStatusCounters'

import type {ChangeStatus$key} from './__generated__/ChangeStatus.graphql'
import type {ChangeStatusBuildsQuery} from './ChangeStatusBuilds/__generated__/ChangeStatusBuildsQuery.graphql'
import ChangeStatusBuilds, {changeStatusBuildsQuery} from './ChangeStatusBuilds/ChangeStatusBuilds'

import styles from './ChangeStatus.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = {
  className?: string
  changeId: ChangeId
}

const POPUP_DIRECTIONS = [Directions.RIGHT_BOTTOM]

const fragment = graphql`
  fragment ChangeStatus on ChangeStatus {
    cancelledBuilds
    pendingBuildTypes
    runningSuccessfullyBuilds
    successfulBuilds
    criticalBuilds {
      count
    }
    newTestsFailedBuilds {
      count
    }
    notCriticalBuilds {
      count
    }
    finishedBuilds
    runningBuilds
    queuedBuildsCount
    totalProblems
    newFailedTests
    otherFailedTests
  }
`

function ChangeStatus({className, changeId}: Props) {
  const {personal} = useAppSelector(state => getChange(state, changeId)) ?? {}

  const changeLocator = `id:${stringifyId(changeId)},personal:${personal || false}`
  const {change} = useLazyLoadQuery<ChangeStatusCountersQuery>(
    changeStatusCountersQuery,
    {changeLocator},
    {fetchPolicy: 'store-only'},
  )
  const status = useFragment<ChangeStatus$key>(fragment, change?.status ?? null)

  const [buildsQueryRef, loadBuildsQuery, disposeBuildsQuery] =
    useQueryLoader<ChangeStatusBuildsQuery>(changeStatusBuildsQuery)

  const criticalFailed =
    (status?.criticalBuilds?.count ?? 0) + (status?.newTestsFailedBuilds?.count ?? 0)
  const failed = status?.notCriticalBuilds?.count ?? 0
  const successful = status?.successfulBuilds ?? 0
  const runningSuccesful = status?.runningSuccessfullyBuilds ?? 0
  const cancelled = status?.cancelledBuilds ?? 0
  const pending = status?.pendingBuildTypes ?? 0
  const finishedBuilds = status?.finishedBuilds ?? 0
  const runningBuilds = status?.runningBuilds ?? 0
  const queuedBuildsCount = status?.queuedBuildsCount ?? 0

  const totalProblems = status?.totalProblems ?? 0
  const newFailedTests = status?.newFailedTests ?? 0
  const otherFailedTests = status?.otherFailedTests ?? 0
  const hasProblems = newFailedTests > 0 || otherFailedTests > 0 || totalProblems > 0

  const stopPropagation = useCallback((e: SyntheticEvent) => {
    e.preventDefault()
    e.stopPropagation()
  }, [])

  const renderAnchor = useCallback(() => {
    const modifiers = []

    if (runningSuccesful > 0) {
      modifiers.push('running')
    } else {
      modifiers.push('finished')
    }

    modifiers.push(!hasProblems ? 'green' : 'red')

    return <Icon name={modifiers.join('_')} onClick={stopPropagation} />
  }, [hasProblems, runningSuccesful, stopPropagation])

  const renderStatusRow = useCallback(
    (key: string, heading: string, value: number, details?: ReactNode) =>
      value > 0 ? (
        <div key={key} className={styles.statusRow}>
          <span className={classNames({[styles.statusRowHeading]: details != null})}>
            {`${value} ${heading}`}
          </span>
          {details}
        </div>
      ) : null,
    [],
  )

  const buildsFallback = <LoaderInline>{'Loading...'}</LoaderInline>
  const renderCriticalBuilds = (
    <div>
      {buildsQueryRef != null ? (
        <Suspense fallback={buildsFallback}>
          <ChangeStatusBuilds queryRef={buildsQueryRef} />
        </Suspense>
      ) : (
        buildsFallback
      )}
    </div>
  )

  return (
    <div className={classNames(className, styles.wrapper)}>
      {runningBuilds > 0 || finishedBuilds > 0 || queuedBuildsCount > 0 ? (
        <Dropdown
          anchor={renderAnchor}
          onShow={() => loadBuildsQuery({changeLocator})}
          onHide={disposeBuildsQuery}
          hoverMode
        >
          <Popup left={5} directions={POPUP_DIRECTIONS}>
            <div className={styles.popup}>
              <H3 className={styles.heading}>
                <RouterLinkWrapper>
                  <Link
                    className={styles.headingLink}
                    href={getChangeHref({changeId, personal, tab: ChangePageTabName.BUILDS})}
                  >
                    {'Builds'}
                  </Link>
                </RouterLinkWrapper>
              </H3>
              {hasProblems
                ? [
                    renderStatusRow(
                      'criticalFailed',
                      `with new or critical problems:`,
                      criticalFailed,
                      renderCriticalBuilds,
                    ),
                    renderStatusRow('failed', 'failed without new problems', failed),
                  ]
                : renderStatusRow('unrelated', 'unrelated failed', criticalFailed + failed)}
              {renderStatusRow('successful', 'successful', successful)}
              {renderStatusRow('runningSuccesful', 'running successfully', runningSuccesful)}
              {renderStatusRow('cancelled', 'cancelled', cancelled)}
              {renderStatusRow('queued', 'queued', queuedBuildsCount)}
              {renderStatusRow('pending', 'pending (not triggered)', pending)}
            </div>
          </Popup>
        </Dropdown>
      ) : null}
    </div>
  )
}

export default ChangeStatus
