import Link from '@jetbrains/ring-ui-built/components/link/link'
import plur from 'plur'
import {memo} from 'react'

import {getChangeHref} from '../../../../../routes'
import type {BuildTypeId, ChangeId} from '../../../../../types'
import RouterLinkWrapper from '../../../../common/RouterLinkWrapper/RouterLinkWrapper'
import {getChange} from '../../Changes.selectors'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = {
  buildTypeId: BuildTypeId | null | undefined
  changeId: ChangeId
}

function ChangeFilesLink({buildTypeId, changeId}: Props) {
  const files = useAppSelector(state => getChange(state, changeId)?.files)
  const personal = useAppSelector(state => getChange(state, changeId)?.personal)
  const count = files?.count ?? 0

  const linkParams = {changeId, buildTypeId, personal}
  const href = getChangeHref(linkParams)

  return (
    <RouterLinkWrapper>
      <Link data-test-change-item={'files'} href={href}>
        {`${count} ${plur('file', count)}`}
      </Link>
    </RouterLinkWrapper>
  )
}

export default memo(ChangeFilesLink)
