import type {GetChangeFilesApiArg} from '../../../../services/rest'
import type {BuildTypeId, ChangeId} from '../../../../types'
import {stringifyId} from '../../../../types'

export const getChangeFilesArg = (
  changeId: ChangeId,
  buildTypeId: BuildTypeId | null | undefined,
  personal?: boolean | undefined,
): GetChangeFilesApiArg => ({
  changeId,
  changeLocator: `id:${stringifyId(changeId)}${personal === true ? `,personal:true` : ''}`,
  fields: 'count,file(file,directory,changeType)',
  buildTypeId,
})
