import Button from '@jetbrains/ring-ui-built/components/button/button'
import {useCallback, useMemo, useState} from 'react'
import {graphql, usePreloadedQuery} from 'react-relay'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import EntityPath from '../../../../../../containers/EntityPath'
import {stringifyId} from '../../../../../../types'
import {emptyArray} from '../../../../../../utils/empty'
import BuildNumberContainer from '../../../../../common/BuildNumber/BuildNumber.container'
import styles from '../ChangeStatus.module.css'

import type {ChangeStatusBuildsQuery} from './__generated__/ChangeStatusBuildsQuery.graphql'

const VISIBLE_BUILDS_COUNT = 10

export const changeStatusBuildsQuery = graphql`
  query ChangeStatusBuildsQuery($changeLocator: String!) {
    change(changeLocator: $changeLocator) {
      status {
        criticalBuilds {
          build {
            id
            buildTypeId
          }
        }
        newTestsFailedBuilds {
          build {
            id
            buildTypeId
          }
        }
      }
    }
  }
`

type Props = {
  queryRef: PreloadedQuery<ChangeStatusBuildsQuery>
}
export default function ChangeStatusBuilds({queryRef}: Props) {
  const {change} = usePreloadedQuery(changeStatusBuildsQuery, queryRef)
  const {status} = change ?? {}
  const criticalBuilds = status?.criticalBuilds?.build ?? emptyArray
  const newTestsFailedBuilds = status?.newTestsFailedBuilds?.build ?? emptyArray

  const [showAll, onShowMore] = useState(false)
  const toggleShowAll = useCallback(() => onShowMore(true), [])

  return useMemo(() => {
    const builds = [...criticalBuilds, ...newTestsFailedBuilds]
    const truncatedBuilds = showAll ? builds : builds.slice(0, VISIBLE_BUILDS_COUNT)
    return (
      <>
        {truncatedBuilds.map(({id, buildTypeId}) => (
          <div className={styles.buildPath} key={stringifyId(id)}>
            <EntityPath
              linkClassName={styles.entityPathLink}
              buildTypeId={buildTypeId}
              projectOrBuildTypeNode={{nodeType: 'all'}}
              withLeafStatusIcon={false}
            />
            <span className={styles.separator}>{'\u00a0/\u00a0'}</span>
            <BuildNumberContainer buildId={id} hideStar />
          </div>
        ))}
        {builds.length > VISIBLE_BUILDS_COUNT && !showAll ? (
          <Button className={styles.showAllButton} onClick={toggleShowAll} inline>
            {'Show all'}
          </Button>
        ) : null}
      </>
    )
  }, [criticalBuilds, newTestsFailedBuilds, showAll, toggleShowAll])
}
