import InjectHtml from '../InjectHtml/InjectHtml'

type Props = {
  className?: string
  path: string
}

function InjectExtensions({className, path}: Props) {
  return (
    <InjectHtml
      className={className}
      path={path}
      TagName="span"
      showLoader={false}
      withLazyLoading
    />
  )
}

export default InjectExtensions
