import {IconButton, SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {useMemo} from 'react'

import type {ChangeId} from '../../../../../types'
import RouterLinkWrapper from '../../../../common/RouterLinkWrapper/RouterLinkWrapper'
import {getChange} from '../../Changes.selectors'

import {
  getBuildChangesTabHref,
  getBuildTypePendingChangesTabHref,
} from './ChangeFromSnapshotDependencyIcon.utils'

import styles from './ChangeFromSnapshotDependencyIcon.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = {
  className?: string
  changeId: ChangeId
}

function ChangeFromSnapshotDependencyIcon({className, changeId}: Props) {
  const changeType = useAppSelector(state => getChange(state, changeId)?.type)
  const {build, buildType, buildTypeBranch} =
    useAppSelector(state => getChange(state, changeId)?.snapshotDependencyLink) ?? {}

  const buildId = build?.id
  const buildTypeId = buildType?.id ?? build?.buildType?.id

  const buildNumber = build?.number
  const buildTypeName = buildType?.name ?? build?.buildType?.name

  const buildChangesTab = buildId != null ? getBuildChangesTabHref(buildId) : null
  const buildTypePendingChangesTab =
    buildTypeId != null
      ? getBuildTypePendingChangesTabHref(buildTypeId, buildTypeBranch)
      : undefined

  const buildTypeNameString = buildTypeName != null ? ` "${buildTypeName}"` : ''
  const buildNumberString = buildNumber != null ? ` #${buildNumber}` : ''

  const commonProps = useMemo(
    () => ({
      className: classNames(className, styles.icon),
      title: `Change from snapshot dependency${buildTypeNameString}${buildNumberString}`,
      icon: 'link',
    }),
    [buildNumberString, buildTypeNameString, className],
  )

  if (changeType !== 'SNAPSHOT_DEPENDENCY_VCS_CHANGE') {
    return null
  }

  if (buildChangesTab == null && buildTypePendingChangesTab == null) {
    return <SvgIcon {...commonProps} />
  }

  return (
    <RouterLinkWrapper>
      <IconButton {...commonProps} href={buildChangesTab ?? buildTypePendingChangesTab} />
    </RouterLinkWrapper>
  )
}

export default ChangeFromSnapshotDependencyIcon
