import {objectEntries} from '@jetbrains/teamcity-ui/dist/utils'
import deepEqual from 'fast-deep-equal'
import plur from 'plur'
import {useCallback, useMemo} from 'react'
import {graphql, useLazyLoadQuery} from 'react-relay'
import {useLocation, useNavigate} from 'react-router'

import {useQueryParam, useQueryParams} from '../../../hooks/routes'
import {getHrefWithQueryParams} from '../../../routes'
import type {BuildTypeId, ChangesType, FilterOptions, ProjectId, UserId} from '../../../types'
import {toProjectId, toUserId} from '../../../types'
import {limitCount, printCount} from '../../../utils/printCount'

import type {ChangesDefaultFilterOptionsQuery} from './__generated__/ChangesDefaultFilterOptionsQuery.graphql'
import {toChangesType} from './Changes.utils'

type ChangesFilterOptions = {
  changesType: ChangesType | null
  versionedSettings: boolean
  userId: UserId | string | null
  username: string | null
  comment: string
  path: string
  revision: string
  fromBuildNumber: string
  toBuildNumber: string
  projectId: ProjectId | null
  showDependenciesChanges: boolean | null
}

type ChangesFilter = {
  filterOptions: ChangesFilterOptions
  isFilterChanged: boolean
  onChangeFilter: (filter: FilterOptions, resetBeforeUpdate?: boolean) => unknown
}

function useDefaultFilterOptions(
  buildTypeId?: BuildTypeId | null | undefined,
): ChangesFilterOptions {
  const {buildType} = useLazyLoadQuery<ChangesDefaultFilterOptionsQuery>(
    graphql`
      query ChangesDefaultFilterOptionsQuery($locator: String!, $skip: Boolean!) {
        buildType(btLocator: $locator) @skip(if: $skip) {
          project {
            internalId
          }
          settings {
            property {
              name
              value
            }
          }
        }
      }
    `,
    {locator: `id:${buildTypeId}`, skip: buildTypeId == null},
  )
  const property = buildType?.settings?.property?.find(
    ({name}) => name === 'showDependenciesChanges',
  )
  const showDependenciesChanges = property?.value === 'true'

  return {
    changesType: null,
    versionedSettings: true,
    userId: null,
    username: null,
    comment: '',
    path: '',
    revision: '',
    fromBuildNumber: '',
    toBuildNumber: '',
    projectId: null,
    showDependenciesChanges: buildTypeId != null ? showDependenciesChanges : null,
  }
}

function useFilterOptions(buildTypeId?: BuildTypeId | null | undefined): ChangesFilterOptions {
  const defaultOptions = useDefaultFilterOptions(buildTypeId)
  const {
    changesType,
    versionedSettings,
    userId,
    username,
    comment,
    path,
    revision,
    fromBuildNumber,
    toBuildNumber,
    projectId,
    showDependenciesChanges,
  } = useQueryParams()

  return {
    changesType: toChangesType(changesType) ?? defaultOptions.changesType,
    username: username ?? defaultOptions.username,
    comment: comment ?? defaultOptions.comment,
    path: path ?? defaultOptions.path,
    revision: revision ?? defaultOptions.revision,
    fromBuildNumber: fromBuildNumber ?? defaultOptions.fromBuildNumber,
    toBuildNumber: toBuildNumber ?? defaultOptions.toBuildNumber,
    projectId: projectId != null ? toProjectId(projectId) : defaultOptions.projectId,
    versionedSettings:
      versionedSettings != null ? versionedSettings === 'true' : defaultOptions.versionedSettings,
    showDependenciesChanges:
      showDependenciesChanges != null
        ? showDependenciesChanges === 'true'
        : defaultOptions.showDependenciesChanges,
    userId: userId !== '' ? (userId != null ? toUserId(userId) : defaultOptions.userId) : '',
  }
}

export function useChangesFilter(buildTypeId?: BuildTypeId | null | undefined): ChangesFilter {
  const location = useLocation()
  const navigate = useNavigate()

  const defaultFilterOptions = useDefaultFilterOptions(buildTypeId)
  const filterOptions = useFilterOptions(buildTypeId)

  return {
    filterOptions,
    isFilterChanged: !deepEqual(filterOptions, defaultFilterOptions),
    onChangeFilter: useCallback(
      (filter, resetBeforeUpdate) => {
        let newParams = {}

        if (resetBeforeUpdate) {
          newParams = Object.fromEntries(
            objectEntries(defaultFilterOptions).map(([key]) => [key, null]),
          )
        }

        newParams = {
          ...newParams,
          ...Object.fromEntries(
            objectEntries(filter).map(([key, value]) => [
              key,
              defaultFilterOptions[key] !== value && (value !== '' || key === 'userId')
                ? String(value)
                : null,
            ]),
          ),
          page: null,
        }

        navigate(
          getHrefWithQueryParams(location, null, params => ({...params, ...newParams})),
          {preventScrollReset: true},
        )
      },
      [defaultFilterOptions, location, navigate],
    ),
  }
}

export function useCurrentPage(paramName = 'page'): number | null {
  const pageQueryParam = useQueryParam(paramName)
  const currentPage = Number(pageQueryParam)

  return !isNaN(currentPage) ? currentPage : null
}

export function useChangesCountHeading(changesCount: number, artifactChangesCount: number) {
  return useMemo(() => {
    const count = changesCount + artifactChangesCount
    const text =
      changesCount === 0 && artifactChangesCount !== 0 ? 'Artifact Dependency Change' : 'Change'
    return `${printCount(count)} ${plur(text, limitCount(count))}`
  }, [changesCount, artifactChangesCount])
}
