import Link from '@jetbrains/ring-ui-built/components/link/link'
import classNames from 'classnames'
import type {SyntheticEvent} from 'react'
import {memo, useMemo} from 'react'

import {useIsAutodetectTimeZone} from '../../../../hooks/useIsAutodetectTimeZone'
import {getChangeHref} from '../../../../routes'
import {stringifyId} from '../../../../types'
import type {ChangeId, RevisionId} from '../../../../types'
import {displayDate} from '../../../../utils/dateTimeUtils'
import CopyIconButton from '../../../common/CopyIconButton/CopyIconButton'
import RouterLinkWrapper from '../../../common/RouterLinkWrapper/RouterLinkWrapper'
import {hasSelection} from '../../../common/Tree/Tree.utils'

import ChangeRevisionDropdown from './ChangeRevisionDropdown/ChangeRevisionDropdown'

import styles from './ChangeRevision.module.css'

const SHOW_VERSION_LENGTH = 12

type Props = {
  className?: string
  copyButtonClassName?: string
  changeId?: ChangeId | undefined | null
  version: RevisionId | undefined | null
  personal?: boolean
  date?: string
  withDetailsPopup?: boolean
  withDetailsPopupShown?: boolean
  withShortView?: boolean
  withCopyButton?: boolean
}

const onClick = (e: SyntheticEvent) => {
  if (hasSelection()) {
    e.stopPropagation()
    e.preventDefault()
  }
}

function ChangeRevision({
  className,
  copyButtonClassName,
  changeId,
  date,
  version,
  personal,
  withDetailsPopup,
  withDetailsPopupShown,
  withCopyButton,
  withShortView,
}: Props) {
  const isAutodetectTimeZone = useIsAutodetectTimeZone()
  const renderRevision = useMemo(() => {
    if (personal === true && date != null) {
      return (
        <span data-test-personal-change-revision-id>
          {displayDate(date, isAutodetectTimeZone, true)}
        </span>
      )
    }

    return (
      <span data-test-change-revision-id>
        {withShortView ? stringifyId(version).slice(0, SHOW_VERSION_LENGTH) : stringifyId(version)}
      </span>
    )
  }, [date, isAutodetectTimeZone, personal, version, withShortView])

  const renderRevisionLink = useMemo(() => {
    if (changeId == null || personal == null) {
      return renderRevision
    }
    const href = getChangeHref({changeId, personal})
    return (
      <RouterLinkWrapper>
        <Link href={href} draggable={false} onClick={onClick}>
          {renderRevision}
        </Link>
      </RouterLinkWrapper>
    )
  }, [changeId, personal, renderRevision])

  if (date == null && version == null) {
    return null
  }

  return (
    <div className={classNames(styles.wrapper, className)}>
      {withDetailsPopup && !personal ? (
        <ChangeRevisionDropdown
          changeId={changeId}
          version={version}
          anchor={renderRevisionLink}
          initShown={withDetailsPopupShown}
        />
      ) : (
        renderRevisionLink
      )}
      {withCopyButton ? (
        <CopyIconButton
          iconClassName={classNames(copyButtonClassName, styles.copyButton)}
          text={version}
          title="Copy full hash to clipboard"
        />
      ) : null}
    </div>
  )
}

export default memo(ChangeRevision)
